import { AuthService } from "../../application/AuthService.js";
import { PrismaRefreshTokenRepository } from "../repositories/PrismaRefreshTokenRepository.js";
import { PrismaUserRepository } from "../repositories/PrismaUserRepository.js";
import { BcryptHasher } from "../providers/BcryptHasher.js";
import { JwtTokenProvider } from "../providers/JwtTokenProvider.js";
import { prisma } from "../../../../shared/config/database.js";
import { env } from "../../../../shared/config/env.js";
import { AuthController } from "../../presentation/controllers/AuthController.js";
import { PrismaPasswordResetTokenRepository } from "../repositories/PrismaPasswordResetTokenRepository.js";
import { ConsoleEmailProvider } from "../providers/ConsoleEmailProvider.js";
export const tokenProvider = new JwtTokenProvider(env.jwtSecret, env.accessTokenTtl);
export const authService = new AuthService(new PrismaUserRepository(prisma), new PrismaRefreshTokenRepository(prisma), new BcryptHasher(), tokenProvider, env.refreshTokenTtlMs, new PrismaPasswordResetTokenRepository(prisma), new ConsoleEmailProvider(), env.passwordResetTtlMs);
export const authController = new AuthController(authService);
